export function ProjectScreen({
  item,
  position,
  width = 12,
  height = 6.75,
  rotation = [0, 0, 0],
  medium = "screen",
  tint = "#497cb0",
}: {
  item: ContentItem;
  position: [number, number, number];
  width?: number;
  height?: number;
  rotation?: [number, number, number];
  tint?: string;
  medium?: "screen" | "print" | "projection";
}) {
  const hovered = useRef(false);
  const frame = useRef<Group>(null);
  const open = () => {
    acknowledge("Opening " + item.title);
    usePalaceStore.getState().focusItem(item);
  };
  const attention = useInteractable(frame, { title: item.title, hint: "View project", radius: 13, activate: open });
  return (
    <group
      ref={frame}
      name={`project:${item.id}`}
      position={position}
      rotation={rotation}
      onPointerOver={() => { hovered.current = true; }}
      onPointerOut={() => { hovered.current = false; }}
      onClick={(e) => {
        if (e.delta < 5) {
          e.stopPropagation();
          open();
        }
      }}
    >
      <Block
        scale={[width + 0.2, height + 0.2, 0.18]}
        color="#0c1723"
        metalness={0.7}
        roughness={0.2}
      />
      <Picture
        src={item.cover}
        medium={medium}
        width={width}
        height={height}
        position={[0, 0, 0.12]}
      />
      <WorkAttention width={width} height={height} hovered={hovered} warm={medium === "print"} attention={attention} />
      <Block
        position={[0, -height / 2 - 0.1, 0]}
        scale={[width, 0.035, 0.22]}
        color={tint}
        emissive={tint}
        emissiveIntensity={0.9}
      />
      <Label
        text={item.title.toUpperCase()}
        position={[-width / 2, -height / 2 - 0.5, 0.2]}
        align="left"
        size={0.2}
        color="#d7e7ee"
      />
      <Label
        text={item.status}
        position={[-width / 2, -height / 2 - 0.83, 0.2]}
        align="left"
        size={0.11}
        color="#90a6b5"
      />
    </group>
  );
}

