    key: listening ? "#ffe3bc" : roomId === "corridor" ? "#e4f3ff" : "#f4f4ec",
    keyIntensity: listening ? 0.16 : archive ? 0.8 : dark ? 0.38 : 2.35,
    environment: listening ? 0.28 : dark ? 0.32 : 0.38,
    dark,
  };
}

